	oldUmask := syscall.Umask(0077) // Owner can read and write only

	// Open the file with appropriate permissions
	fd, err := os.OpenFile(filepath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
