const xpath = require('xpath');

function getStudentInfo(xml_data, username, password) {
    // Validate inputs to ensure they are alphanumeric
    const validInput = /^[a-zA-Z0-9_]+$/;
    if (!validInput.test(username) || !validInput.test(password)) {
        return null;
    }

    const dom = new JSDOM(xml_data, { contentType: "application/xml" });
    const doc = dom.window.document;
    const select = xpath.useNamespaces({ "x": "http://www.w3.org/1999/xhtml" });

    // Use XPath variables to safely incorporate user inputs
    const query = `/students/student[username[text()=$username] and password[text()=$password]]`;
    const variables = {
        username: username,
        password: password
    };
    const studentNode = select(query, doc, true, variables);

    if (studentNode) {
        const name = select('string(./name)', studentNode);
        const age = select('string(./age)', studentNode);
        const citizenship = select('string(./citizenship)', studentNode);

        return {
            name: name,
            age: age,
            citizenship: citizenship
        };
    }

    return null;
}

